import {loopBank,loopQuestion,answerQuestion,loopReason,loopEvidence,reviewLists} from './loop-model.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=s=>new Date(s).toLocaleString('zh-CN');
const result=a=>!a?'未作答':a.correct?'答对':'未答对';
const choice=a=>a?.choice===null?'我还不会':a?.choice??'未作答';
const heading=(title,sub)=>`<div class="workspace-heading"><a class="back" href="#">← 选科首页</a><div><h1>${title}</h1><p>${sub}</p></div></div>`;
const boundary='<p class="workspace-note">本地规则模拟 · 未接 DeepSeek · 固定原创题库，不生成任意题目或视频 · 不代表掌握</p>';
function control(r,action,label,value=null,disabled=false,cls='primary'){return `<button class="${cls}" data-loop-action="${action}" data-loop-id="${r.id}" data-loop-revision="${r.revision}"${['select','guide'].includes(action)?` aria-pressed="${action==='select'?r.selected===value:r.guides[r.phase==='guide2'?1:0]?.choice===value}"`: ''}${value===null?'':` data-loop-value="${esc(value)}"`}${disabled?' disabled':''}>${label}</button>`;}
function evidenceRows(r){const rows=[['first','首次独立选择'],['retry','引导后原题再试'],['transfer','另一道同类题 · 独立选择']];return rows.map(([role,label])=>{const a=r.answers.find(a=>a.role===role);if(!a&&role!=='first')return '';return `<div class="summary-row"><strong>${label}</strong><span>${esc(choice(a))} · ${result(a)}</span></div>`;}).join('');}
export function loopMarkup(r){const subject=loopBank[r.subject],q=loopQuestion(r),first=r.answers[0];
 if(r.phase==='complete')return `<div class="learning-workspace completion-workspace">${heading(subject.label+' · 这次的小步记录',r.kind==='review'?(r.early?'开始时提前复习 · 本次已完成':'本次复习完成'):'引导与新题分别记录')}<div class="workspace-grid"><section class="question-card work-question"><div class="question-content"><span class="chip">${r.kind==='review'?'复习题':'同类新题'} · ${result(r.answers.at(-1))}</span><h2 class="question-title">${esc(q.question)}</h2><div class="feedback good"><strong>这题的思路</strong>${esc(q.explanation)}</div><p class="muted">${r.kind==='review'?'有限题库中的固定复习题，后续可能重复。':'同类新题只记录这一次独立选择，答案在提交后才展示。'}</p></div><div class="question-actions"><a class="secondary" href="#parent">看家长小结</a><a class="primary" href="#reviews">看复习安排 →</a></div></section><aside class="guide-pane"><div class="guide-content"><h2>把每一步分开看</h2><div class="summary">${evidenceRows(r)}</div><p>下一次：<strong>${r.schedule.due}</strong>（设备本地日期）</p><p class="muted">规则：同类题或复习题独立答对，3 天后再看；否则 1 天后。按提交时的本地日期判断是否提前：提前练不推迟原到期日，未答对可提前到次日；已有更早安排不会被新练习推迟。</p><p>看过引导、答案后答对只算引导后作答，不算独立掌握。</p></div><div class="guide-actions"><a class="primary" href="#">回选科首页</a>${r.kind==='practice'?`<button class="secondary" data-loop-restart="${r.subject}">再做这组固定示例</button>`:''}</div></aside></div>${boundary}</div>`;
 const guiding=['guide1','guide2'].includes(r.phase),i=r.phase==='guide2'?1:0,step=q.steps[i],g=r.guides[i];
 const label=r.phase==='initial'?'先独立试一试':r.phase==='retry'?'引导后，再试原题':r.phase==='transfer'?'换一道同类新题':'一步一步想';
 const choices=guiding?`<p class="instruction">原始选择已保留。请回答下一个小问题。</p><div class="feedback"><strong>第一次选了：${esc(choice(first))}</strong>${esc(loopReason(r))}</div>`:`<p class="instruction">${r.phase==='retry'?'提示已看过，这次单独记录。':'先自己选择，提交后再看答案。'}</p><div class="choices" role="group" aria-label="选择答案">${q.choices.map(c=>control(r,'select',`<strong>${esc(c)}</strong>`,c,false,'choice '+(r.selected===c?'selected':''))).join('')}</div>`;
 let guide,actions='';
 if(guiding){guide=`<span class="chip">引导 ${i+1} / 2</span><h2>${esc(step.question)}</h2><div class="loop-guide-choices">${step.choices.map(c=>control(r,'guide',esc(c),c,!!g,'secondary '+(g?.choice===c?'selected':''))).join('')}</div>${g?`<div class="hint" role="status"><strong>${g.correct?'这个方向对了':'一起再看一看'}</strong><p>${esc(step.explanation)}</p></div>`:'<p class="muted">只选择，不填写或录音。</p>'}`;actions=control(r,'next',i===0?'接着想一步 →':'回原题再试 →',null,!g);}
 else if(r.phase==='retry'){guide=`<h2>带着思路再试一次</h2><p>${esc(q.steps[0].explanation)}</p><p>${esc(q.steps[1].explanation)}</p><p class="muted">这次即使答对，也记录为“引导后原题再试”，不会覆盖首次选择。</p>`;}
 else if(r.phase==='transfer'){const prior=r.answers.at(-1),original=loopBank[r.subject].items[0];guide=`<span class="chip">原题小结</span><h2>${prior.role==='retry'?'引导后':'首次'}${result(prior)}</h2><p>${esc(original.explanation)}</p><p>现在换一道同类题，先独立试一次。</p><p class="muted">新题未提交前不显示新题答案。这是固定原创题，不是模型即时出题。</p>`;}
 else guide=`<span class="guide-symbol" aria-hidden="true">${r.kind==='review'?'↻':'步'}</span><h2>${r.kind==='review'?'再看看这个知识点':'不着急，先试一下'}</h2><p>先记录你的第一次选择；需要帮助时，再回答两个小问题。</p><p class="muted">${r.kind==='review'?`原定 ${r.reviewDue}。${r.early?'本次开始时是提前练习。提交时若已到期，将按提交结果安排下一次。':'本次开始时已到期，可以慢慢想。'} 固定复习题可能重复。`:'数学、语文、英语各有一个有限示例闭环。'}</p>`;
 return `<div class="learning-workspace loop-workspace">${heading(subject.label+' · '+subject.topic,label)}<div class="workspace-grid"><section class="question-card work-question"><div class="question-content"><div class="question-meta"><span class="chip">${r.kind==='review'?'本地复习':'小步引导'}</span><span>${label}</span></div><h2 class="question-title" tabindex="-1">${esc(q.question)}</h2>${choices}</div><div class="question-actions">${guiding?'<span class="muted">首次选择不会被修改</span><a class="secondary" href="#reviews">复习安排</a>':control(r,'skip','我还不会',null,false,'text-button')+control(r,'submit','检查答案',null,r.selected===null)}</div></section><aside class="guide-pane"><div class="guide-content">${guide}</div>${actions?`<div class="guide-actions">${actions}</div>`:''}</aside></div>${boundary}</div>`;
}
export function reviewMarkup(p,at=new Date()){const lists=reviewLists(p,at),section=(title,list)=>`<h2>${title}</h2>${list.length?list.map(t=>`<article class="summary-row"><div><strong>${loopBank[t.subject].label} · ${loopBank[t.subject].topic}</strong><p>到期日 ${t.due} · 设备本地日期</p></div><button class="primary" data-loop-review="${t.subject}">${t.due>lists.day?'提前练一次':'开始 / 继续复习'}</button></article>`).join(''):'<p class="empty-state">暂无安排</p>'}`;return `<div class="page-heading"><a class="back" href="#">← 选科首页</a><h1>本地复习安排</h1><p>今天 ${lists.day}。仅在打开页面时计算到期；没有通知、云端定时器或跨设备同步。</p></div>${section('今日及逾期',lists.due)}${section('将来到期',lists.future)}<p class="privacy-note">提前练会如实标记，不推迟原到期日；未答对可提前到次日。有限复习题会重复，答对不代表已经掌握。清除本档案也会清除这些安排。</p>`;}
export function loopParentMarkup(p){const rows=loopEvidence(p);return `<section class="loop-parent"><h2>小步引导 · 按实际选择留证</h2>${rows.length?rows.slice().reverse().map(({run:r})=>`<article class="question-card"><strong>${loopBank[r.subject].label} · ${r.kind==='review'?(r.early?'开始时提前复习':'复习'):'小步引导'} · ${r.completedAt?'已完成':'进行中'}</strong><p>${when(r.startedAt)} · ${r.guides.length} 步引导（${r.guides.filter(g=>g.correct).length} 步首次选择正确）</p><div class="summary">${evidenceRows(r)}</div>${r.schedule?`<p>当时安排：${r.schedule.due}。当前安排请看复习列表。</p>`:''}<p class="muted">${r.kind==='review'?'固定复习题可能已见过，不据此判断掌握。':'不同同类题的结果独立保留，不用原题订正代替。'}</p></article>`).join(''):'<p class="empty-state">尚无小步引导记录。不填入示例成绩。</p>'}<a class="secondary" href="#reviews">查看本地复习安排</a></section>`;}
export function loopWrongsMarkup(p){const rows=loopEvidence(p).flatMap(({run,wrongs})=>wrongs.map(a=>({run,a})));return `<section><h2>小步引导 · 原始未答对记录</h2>${rows.length?rows.slice().reverse().map(({run:r,a})=>`<article class="question-card"><span class="chip">${loopBank[r.subject].label} · ${a.role==='retry'?'引导后原题':a.role==='transfer'?'同类新题':'首次选择'}${r.early?' · 开始时提前复习':''}</span><h3>${esc(answerQuestion(r,a).question)}</h3><p>原来选择：${esc(choice(a))} · ${when(a.at)}</p><p>正确答案：${esc(answerQuestion(r,a).answer)}</p><p>${esc(a.choice===null?'这次选择了“我还不会”。':answerQuestion(r,a).why[a.choice])}</p><p class="muted">原始记录不因后续答对而删除。家长小结可查看各阶段结果。</p></article>`).join(''):'<p class="muted">尚无小步引导的未答对记录。</p>'}</section>`;}
